void dei_rs_push_valet( void )
{		
	if( !get_ss_arm() && (!dei_rs_state) )
	{
		set_rs_valet( !get_rs_valet() );

		dei_prk_flash(  get_rs_valet() ? DEI_PRK_RS_VALET_ON :   DEI_PRK_RS_VALET_OFF );

		notify_send( get_rs_valet() ? NOTIFY_RS_VALET_ON : NOTIFY_RS_VALET_OFF );

		dei_siren_chirp(get_rs_valet() ? DEI_SIREN_RS_VALET_ON : DEI_SIREN_RS_VALET_OFF);

		cmd_q_rs_insert(INPUT_PRG_MODE_EXIT, 100);
	}
	else
	{
		notify_send( NOTIFY_ERROR, NOTIFY_PLD_ERROR_RS_VALET );
	}

}

